"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import Order
from orders.infrastructure.customers import InMemoryCustomerRepository


class CustomerInsightsController:
    def __init__(self, service: OrderService, customers: InMemoryCustomerRepository) -> None:
        self._service = service
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals including any discount."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        history: list[dict[str, Any]] = []
        for order in reversed(orders):  # repository returns creation order
            summary = self._service.summarize(order)
            history.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders that are not cancelled."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, total = self._active_totals(orders)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value (highest first, then customer_id), zero-value excluded."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, total = self._active_totals(self._service.list_for_customer(customer.customer_id))
            if total > 0:
                ranked.append((total, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": customer.customer_id, "name": customer.name, "lifetime_value_cents": total}
            for total, customer in ranked[:limit]]})

    def _active_totals(self, orders: list[Order]) -> tuple[int, int]:
        """Number of non-cancelled orders and the sum of their totals."""
        active = [order for order in orders if order.status != "cancelled"]
        return len(active), sum(self._service.summarize(order).total_cents for order in active)

